_KERNEL = None


def _get_kernel():
    global _KERNEL
    if _KERNEL is None:
        _KERNEL = _PanelKernel()
    return _KERNEL


def _next_pow2(x):
    p = 1
    while p < x:
        p <<= 1
    return p


def _qr(A, nb):
    B, n, _ = A.shape
    H = A.clone()
    tau = torch.zeros((B, n), device=A.device, dtype=A.dtype)
    kern = _get_kernel()

    for k in range(0, n, nb):
        ib = min(nb, n - k)
        L = n - k
        BLOCK_L = _next_pow2(L)
        BLOCK_IB = _next_pow2(ib)

        # threads: cap at L rounded up, but no more than 1024
        nthreads = min(1024, max(64, ((L + 31) // 32) * 32))

        V = torch.empty((B, BLOCK_L, BLOCK_IB), device=A.device, dtype=A.dtype)
        T = torch.empty((B, BLOCK_IB, BLOCK_IB), device=A.device, dtype=A.dtype)
        kern.launch(H, tau, V, T, B, n, k, ib, BLOCK_L, BLOCK_IB, nthreads)

        rest = n - (k + ib)
        if rest > 0:
            Vc = V[:, :L, :ib]            # (B, L, ib)
            Tc = T[:, :ib, :ib]           # (B, ib, ib)
            C = H[:, k:n, k + ib:n]        # (B, L, rest)
            W = torch.bmm(Vc.transpose(1, 2), C)     # V^T C
            W = torch.bmm(Tc.transpose(1, 2), W)      # T^T W
            torch.baddbmm(C, Vc, W, beta=1.0, alpha=-1.0, out=C)   # C - V W (fused)

    return H, tau


def custom_kernel(data: input_t) -> output_t:
    n = data.shape[-1]
    nb = 16 if n >= 2048 else 32
    return _qr(data, nb)

