import torch
from task import input_t, output_t

# =============================================================================
# Blocked compact-WY Householder QR (geqrf-compatible), batched.
#
# Right-looking block algorithm (LAPACK dgeqrf structure). The per-panel
# factorization (unblocked geqr2 over `ib` columns + clean unit-trapezoidal V +
# the ib x ib block reflector T) runs in ONE custom CUDA kernel, ONE THREAD
# BLOCK PER MATRIX, with the L x ib panel tile resident in SHARED MEMORY (not
# per-thread registers). This lifts the occupancy ceiling that a register-tiled
# Triton panel kernel hits (1 block/SM, 12.5% warp occupancy on the 512x32 FP32
# tile). The kernel is compiled at import time with NVRTC (cuda-python bindings)
# and launched through the CUDA driver API with tensor.data_ptr() on torch's
# current (default) stream -- no torch.utils.cpp_extension (blocked here under
# gcc-13/nvcc-13.3), no extra CUDA stream, no per-call host sync/malloc, so the
# whole thing stays graph-capture-safe.
#
# The trailing update C := (I - V T^T V^T) C is then 3 batched cuBLAS GEMMs
# (bmm V^T C, bmm T^T W, baddbmm C - V W fused), unchanged from the prior best.
#
# Output matches torch.geqrf exactly: H holds R on/above the diagonal and the
# reflector vectors v_i below the diagonal of column i (implicit unit diagonal);
# tau holds the reflector coefficients.
# =============================================================================

torch.backends.cuda.matmul.allow_tf32 = False
torch.backends.cudnn.allow_tf32 = False


# ---------------------------------------------------------------------------
# CUDA panel kernel source.
#
# Grid: (B,). Block: NT threads (1D). One block factors matrix `bid`'s panel
#   A[k:n, k:k+ib]  (height L = n-k, width ib).
#
# Shared memory (dynamic, column-major panel for coalesced per-column access):
#   sA : L*ib  floats  -- the live panel tile (R + reflectors)
#   sv : L     floats  -- the current Householder vector v_j (unit on row j)
#   sw : ib    floats  -- per trailing-column dot products w[c] = v_j . A[:,c]
#   sT : ib*ib floats  -- the block reflector T (column-major)
#   sred: NT/32 floats -- block-reduction scratch (one per warp)
# All laid contiguously; the host computes the byte size and sets the
# max-dynamic-smem attribute so >48KB is allowed.
# ---------------------------------------------------------------------------
_CUDA_SRC = r'''
extern "C" __global__ void qr_panel(
        float* __restrict__ H,      // (B, n, n) row-major
        float* __restrict__ tau,    // (B, n)
        float* __restrict__ V,      // (B, BL, BIB) row-major (clean unit-trapz)
        float* __restrict__ T,      // (B, BIB, BIB) row-major
        const int B, const int n, const int k, const int ib,
        const int BL, const int BIB) {

    const int bid = blockIdx.x;
    if (bid >= B) return;

    const int L  = n - k;
    const int NT = blockDim.x;
    const int tid = threadIdx.x;
    const int lane = tid & 31;
    const int warp = tid >> 5;
    const int nwarps = (NT + 31) >> 5;

    extern __shared__ float smem[];
    float* sA  = smem;                 // L*ib
    float* sv  = sA + L * ib;          // L
    float* sw  = sv + L;               // ib
    float* sT  = sw + ib;              // ib*ib
    float* sred = sT + ib * ib;        // nwarps

    // ---- load panel A[k:n, k:k+ib] (row-major in H) into sA (column-major) ----
    float* Abase = H + (long)bid * n * n + (long)k * n + k;
    for (int idx = tid; idx < L * ib; idx += NT) {
        int c = idx / L;               // column
        int r = idx - c * L;           // row
        sA[idx] = Abase[(long)r * n + c];
    }
    __syncthreads();

    // ----------------------- unblocked geqr2 over ib columns -----------------
    for (int j = 0; j < ib; ++j) {
        // alpha = sA[j,j]; xnorm_sq = sum_{r>j} sA[r,j]^2
        float* colj = sA + (long)j * L;
        float partial = 0.0f;
        for (int r = j + 1 + tid; r < L; r += NT) {
            float x = colj[r];
            partial += x * x;
        }
        // warp reduce
        #pragma unroll
        for (int off = 16; off > 0; off >>= 1)
            partial += __shfl_down_sync(0xffffffff, partial, off);
        if (lane == 0) sred[warp] = partial;
        __syncthreads();
        float xnorm_sq = 0.0f;
        if (warp == 0) {
            float v = (lane < nwarps) ? sred[lane] : 0.0f;
            #pragma unroll
            for (int off = 16; off > 0; off >>= 1)
                v += __shfl_down_sync(0xffffffff, v, off);
            if (lane == 0) sred[0] = v;
        }
        __syncthreads();
        xnorm_sq = sred[0];

        float alpha = colj[j];
        float sgn = (alpha >= 0.0f) ? 1.0f : -1.0f;
        float beta = -sgn * sqrtf(alpha * alpha + xnorm_sq);
        bool nonzero = xnorm_sq > 0.0f;
        float beta_safe = nonzero ? beta : 1.0f;
        float tau_j = nonzero ? (beta - alpha) / beta_safe : 0.0f;
        float diagval = nonzero ? beta : alpha;
        float denom = nonzero ? (alpha - beta) : 1.0f;

        // build v into sv (unit on row j, 0 above, A/denom below) -- only valid rows
        for (int r = tid; r < L; r += NT) {
            float vv;
            if (r < j) vv = 0.0f;
            else if (r == j) vv = 1.0f;
            else vv = nonzero ? (colj[r] / denom) : 0.0f;
            sv[r] = vv;
        }
        // finalize column j storage: diag=diagval, below=v, above unchanged
        if (tid == 0) colj[j] = diagval;
        __syncthreads();
        for (int r = j + 1 + tid; r < L; r += NT) colj[r] = sv[r];

        if (tid == 0) tau[(long)bid * n + (k + j)] = tau_j;
        __syncthreads();

        // ---- apply reflector to trailing columns c in (j, ib) ----
        // w[c] = sum_r sv[r] * sA[r,c]   (only r>=j contribute, sv=0 below... above j)
        // Parallelize: each warp handles a subset of columns, reduces over rows.
        for (int c = j + 1 + warp; c < ib; c += nwarps) {
            float* colc = sA + (long)c * L;
            float acc = 0.0f;
            for (int r = j + lane; r < L; r += 32)
                acc += sv[r] * colc[r];
            #pragma unroll
            for (int off = 16; off > 0; off >>= 1)
                acc += __shfl_down_sync(0xffffffff, acc, off);
            if (lane == 0) sw[c] = acc;
        }
        __syncthreads();
        // sA[:,c] -= tau_j * w[c] * sv[:]   for c>j
        for (int idx = tid; idx < (ib - j - 1) * L; idx += NT) {
            int cc = idx / L;            // 0-based within trailing
            int r = idx - cc * L;
            int c = j + 1 + cc;
            sA[(long)c * L + r] -= tau_j * sw[c] * sv[r];
        }
        __syncthreads();
    }

    // ----------------------- emit clean unit-trapezoidal V -------------------
    // V (BL, BIB) row-major: 1 on diag, sA below diag (for valid r<L,c<ib), 0 else.
    float* Vbase = V + (long)bid * BL * BIB;
    for (int idx = tid; idx < BL * BIB; idx += NT) {
        int r = idx / BIB;
        int c = idx - r * BIB;
        float val = 0.0f;
        if (r < L && c < ib) {
            if (r == c) val = 1.0f;
            else if (r > c) val = sA[(long)c * L + r];
        }
        Vbase[idx] = val;
    }

    // ----------------------- write panel back to H ---------------------------
    for (int idx = tid; idx < L * ib; idx += NT) {
        int c = idx / L;
        int r = idx - c * L;
        Abase[(long)r * n + c] = sA[idx];
    }
    __syncthreads();

    // ----------------------- form T (dlarft forward recurrence) --------------
    // T is BIB x BIB upper-triangular, column-major scratch sT, then store.
    // T[:,0] = (tau_0, 0, 0, ...). For j=1..ib-1:
    //   z[i] = sum_r V[r,i]*V[r,j] = sum_r sv stored... use sA columns.
    //   Note V[:,c] = unit-trapz of column c: V[c,c]=1, V[r,c]=sA[r,c] for r>c.
    //   z[i<j] = (V[:,i]) . (V[:,j]).  T[:,j] = -tau_j * T[:,0:j] @ z[0:j]; T[j,j]=tau_j.
    // We compute with one warp per column-i dot, sequentially over j.
    // Initialize sT = 0
    for (int idx = tid; idx < ib * ib; idx += NT) sT[idx] = 0.0f;
    __syncthreads();
    if (tid == 0) sT[0] = tau[(long)bid * n + (k + 0)];   // sT[0 + 0*ib]
    __syncthreads();

    for (int j = 1; j < ib; ++j) {
        float tau_j = tau[(long)bid * n + (k + j)];
        // z[i] for i<j : dot of V[:,i] and V[:,j]
        // V[:,i] : V[i,i]=1, V[r,i]=sA[r,i] for r>i (r<L)
        // V[:,j] : V[j,j]=1, V[r,j]=sA[r,j] for r>j
        // compute into sw[i] (reuse) for i<j
        for (int i = warp; i < j; i += nwarps) {
            float acc = 0.0f;
            // overlap rows: both nonzero for r in [j, L) plus the unit terms.
            // V[r,i]*V[r,j]: for r=i: 1 * V[i,j]; but i<j so V[i,j]=0 (above diag of col j) -> 0
            //   for r=j: V[j,i]*1 = sA[j,i] (since j>i)
            //   for r>j: sA[r,i]*sA[r,j]
            // start r at j
            float* coli = sA + (long)i * L;
            float* colcj = sA + (long)j * L;
            // r=j term: sA[j,i]*1
            for (int r = j + lane; r < L; r += 32) {
                float vi = (r == j) ? coli[j] : coli[r];   // V[r,i]
                float vj = (r == j) ? 1.0f : colcj[r];     // V[r,j]
                acc += vi * vj;
            }
            #pragma unroll
            for (int off = 16; off > 0; off >>= 1)
                acc += __shfl_down_sync(0xffffffff, acc, off);
            if (lane == 0) sw[i] = acc;
        }
        __syncthreads();
        // T[:,j] (rows 0..j-1) = -tau_j * sum_{m<j} T[:,m] * sw[m]; T[j,j]=tau_j
        // one thread per row i<j
        for (int i = tid; i < j; i += NT) {
            float t = 0.0f;
            for (int m = 0; m < j; ++m)
                t += sT[(long)m * ib + i] * sw[m];   // T[i,m] col-major: sT[i + m*ib]
            sT[(long)j * ib + i] = -tau_j * t;
        }
        __syncthreads();
        if (tid == 0) sT[(long)j * ib + j] = tau_j;
        __syncthreads();
    }

    // store T (BIB x BIB) row-major to global: T_global[r,c] = sT[r + c*ib]
    float* Tbase = T + (long)bid * BIB * BIB;
    for (int idx = tid; idx < BIB * BIB; idx += NT) {
        int r = idx / BIB;
        int c = idx - r * BIB;
        float val = (r < ib && c < ib) ? sT[(long)c * ib + r] : 0.0f;
        Tbase[idx] = val;
    }
}
'''


