        // (its alpha read) and colj[r] (the sv build) before thread 0 overwrites
        // colj[j]=diagval -- otherwise a slow warp reads the post-write diagval
        // as alpha and corrupts that matrix (a cross-warp smem hazard that only
        // surfaces under heavy SM contention, i.e. large batches).
        __syncthreads();
        // finalize column j storage: diag=diagval, below=v, above unchanged
        if (tid == 0) colj[j] = diagval;
        __syncthreads();
        for (int r = j + 1 + tid; r < L; r += NT) colj[r] = sv[r];

        if (tid == 0) tau[(long)bid * n + (k + j)] = tau_j;
        __syncthreads();

        // ---- apply reflector to trailing columns c in (j, ib) ----
        // w[c] = sum_r sv[r] * sA[r,c]   (only r>=j contribute, sv=0 below... above j)
        // Parallelize: each warp handles a subset of columns, reduces over rows.
        for (int c = j + 1 + warp; c < ib; c += nwarps) {
            float* colc = sA + (long)c * L;
            float acc = 0.0f;
            for (int r = j + lane; r < L; r += 32)
                acc += sv[r] * colc[r];
            #pragma unroll
            for (int off = 16; off > 0; off >>= 1)
                acc += __shfl_down_sync(0xffffffff, acc, off);
            if (lane == 0) sw[c] = acc;
        }
        __syncthreads();
        // sA[:,c] -= tau_j * w[c] * sv[:]   for c>j
        for (int idx = tid; idx < (ib - j - 1) * L; idx += NT) {
            int cc = idx / L;            // 0-based within trailing
            int r = idx - cc * L;
            int c = j + 1 + cc;
            sA[(long)c * L + r] -= tau_j * sw[c] * sv[r];
        }
        __syncthreads();
    }

    // ----------------------- emit clean unit-trapezoidal V -------------------
    // V (BL, BIB) row-major: 1 on diag, sA below diag (for valid r<L,c<ib), 0 else.
    float* Vbase = V + (long)bid * BL * BIB;
    for (int idx = tid; idx < BL * BIB; idx += NT) {
        int r = idx / BIB;
        int c = idx - r * BIB;
        float val = 0.0f;
        if (r < L && c < ib) {
            if (r == c) val = 1.0f;
            else if (r > c) val = sA[(long)c * L + r];
        }
        Vbase[idx] = val;
    }

    // ----------------------- write panel back to H ---------------------------
    for (int idx = tid; idx < L * ib; idx += NT) {
        int c = idx / L;
        int r = idx - c * L;
        Abase[(long)r * n + c] = sA[idx];
    }
    __syncthreads();

    // ----------------------- form T (dlarft forward recurrence) --------------
    // T is BIB x BIB upper-triangular, column-major scratch sT, then store.
    // T[:,0] = (tau_0, 0, 0, ...). For j=1..ib-1:
    //   z[i] = sum_r V[r,i]*V[r,j] = sum_r sv stored... use sA columns.
    //   Note V[:,c] = unit-trapz of column c: V[c,c]=1, V[r,c]=sA[r,c] for r>c.
    //   z[i<j] = (V[:,i]) . (V[:,j]).  T[:,j] = -tau_j * T[:,0:j] @ z[0:j]; T[j,j]=tau_j.
    // We compute with one warp per column-i dot, sequentially over j.
    // Initialize sT = 0
    for (int idx = tid; idx < ib * ib; idx += NT) sT[idx] = 0.0f;
    __syncthreads();
    if (tid == 0) sT[0] = tau[(long)bid * n + (k + 0)];   // sT[0 + 0*ib]
    __syncthreads();

    for (int j = 1; j < ib; ++j) {
        float tau_j = tau[(long)bid * n + (k + j)];
        // z[i] for i<j : dot of V[:,i] and V[:,j]
        // V[:,i] : V[i,i]=1, V[r,i]=sA[r,i] for r>i (r<L)
        // V[:,j] : V[j,j]=1, V[r,j]=sA[r,j] for r>j
        // compute into sw[i] (reuse) for i<j
        for (int i = warp; i < j; i += nwarps) {
            float acc = 0.0f;
            // overlap rows: both nonzero for r in [j, L) plus the unit terms.
            // V[r,i]*V[r,j]: for r=i: 1 * V[i,j]; but i<j so V[i,j]=0 (above diag of col j) -> 0
            //   for r=j: V[j,i]*1 = sA[j,i] (since j>i)
            //   for r>j: sA[r,i]*sA[r,j]
            // start r at j
            float* coli = sA + (long)i * L;
            float* colcj = sA + (long)j * L;
            // r=j term: sA[j,i]*1
            for (int r = j + lane; r < L; r += 32) {
                float vi = (r == j) ? coli[j] : coli[r];   // V[r,i]
                float vj = (r == j) ? 1.0f : colcj[r];     // V[r,j]
                acc += vi * vj;
            }
            #pragma unroll
            for (int off = 16; off > 0; off >>= 1)
                acc += __shfl_down_sync(0xffffffff, acc, off);
            if (lane == 0) sw[i] = acc;
        }
        __syncthreads();
        // T[:,j] (rows 0..j-1) = -tau_j * sum_{m<j} T[:,m] * sw[m]; T[j,j]=tau_j
        // one thread per row i<j
        for (int i = tid; i < j; i += NT) {
            float t = 0.0f;
            for (int m = 0; m < j; ++m)
                t += sT[(long)m * ib + i] * sw[m];   // T[i,m] col-major: sT[i + m*ib]
            sT[(long)j * ib + i] = -tau_j * t;
        }
        __syncthreads();
        if (tid == 0) sT[(long)j * ib + j] = tau_j;
        __syncthreads();
    }

    // store T (BIB x BIB) row-major to global: T_global[r,c] = sT[r + c*ib]
    float* Tbase = T + (long)bid * BIB * BIB;
    for (int idx = tid; idx < BIB * BIB; idx += NT) {
        int r = idx / BIB;
        int c = idx - r * BIB;
        float val = (r < ib && c < ib) ? sT[(long)c * ib + r] : 0.0f;
        Tbase[idx] = val;
    }
}

